import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, step, min, max, clamp } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, BoxGeometry } = ctx.THREE;

  // ---------- Panel ----------
  const panelWidth = 3.4;
  const panelHeight = 1.9;

  const panelGeo = new PlaneGeometry(panelWidth, panelHeight);
  const uvNode = uv();

  // Gradient colors (linear space approximations)
  const topColor = vec3(0.10196, 0.10196, 0.13333);   // #1a1a22
  const bottomColor = vec3(0.06667, 0.06667, 0.09020); // #111116
  const gradient = mix(topColor, bottomColor, uvNode.y);

  // Border (hairline 0.006 UV units)
  const edgeDist = min(
    min(uvNode.x, 1.0 - uvNode.x),
    min(uvNode.y, 1.0 - uvNode.y)
  );
  const borderMask = step(edgeDist, 0.006);
  const borderColor = vec3(0.14902, 0.14902, 0.18431); // #26262f
  const panelColorNode = mix(gradient, borderColor, borderMask);

  const panelMat = new MeshStandardNodeMaterial({
    colorNode: panelColorNode,
    metalness: 0.2,
    roughness: 0.6,
    clearcoat: 0.1,
    transparent: true,
    opacity: 0,
  });

  const panelMesh = new Mesh(panelGeo, panelMat);
  panelMesh.position.set(0, 0, 0);
  // ---------- Quote Mark ----------
  const quoteMark = ctx.fontAtlas.createText('“', {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left',
  });
  quoteMark.position.set(-panelWidth / 2 + 0.5, panelHeight / 2 - 0.5, 0.04);
  quoteMark.scale.set(1.04, 1.04, 1.04); // start with overshoot

  // ---------- Quote Text ----------
  const quoteText = ctx.fontAtlas.createText(
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.',
    {
      fontSize: 20,
      color: '#e8ecf2',
      align: 'left',
      maxWidthPx: 2400,
    }
  );
  quoteText.position.set(
    -panelWidth / 2 + 0.5,
    panelHeight / 2 - 0.5 - 0.62 - 0.25,
    0.03
  );

  // ---------- Attribution Rule ----------
  const ruleGeo = new BoxGeometry(0.2, 0.02, 0.01);
  const ruleMat = new MeshStandardNodeMaterial({
    color: 0xff2a38,
    emissive: 0xff2a38,
    emissiveIntensity: 1.4,
    metalness: 0,
    roughness: 0.9,
    transparent: true,
    opacity: 0,
  });
  const ruleMesh = new Mesh(ruleGeo, ruleMat);
  const attrY =
    quoteText.position.y - 0.25; // place below quote text with baseline gap
  ruleMesh.position.set(-panelWidth / 2 + 0.5 + 0.12, attrY, 0.04);

  // ---------- Attribution Text ----------
  const attribution = ctx.fontAtlas.createText('M. OKAFOR', {
    fontSize: 13,
    color: '#ff2a38',
    align: 'left',
    letterSpacingPx: 0.08,
  });
  attribution.position.set(ruleMesh.position.x + 0.15, attrY, 0.04);

  // ---------- Caption ----------
  const caption = ctx.fontAtlas.createText('COLLECTOR SINCE 2019', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: 0.12,
  });
  caption.position.set(
    attribution.position.x,
    attrY - 0.12,
    0.04
  );

  // ---------- Assemble ----------
  const root = new Group();
  root.add(panelMesh);
  root.add(quoteMark);
  root.add(quoteText);
  root.add(ruleMesh);
  root.add(attribution);
  root.add(caption);

  // Initial transform for fade‑up
  root.position.y += 0.2;

  // Ensure all materials are transparent for opacity animation
  root.traverse((obj) => {
    if (obj.isMesh && obj.material) {
      obj.material.transparent = true;
      obj.material.opacity = 0;
    }
  });

  // ---------- Animation ----------
  const timelines = [];

  // Fade‑up of whole panel
  const fadeObj = { opacity: 0 };
  const fadeTL = gsap.timeline();
  fadeTL
    .to(root.position, {
      y: 0,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    })
    .to(
      fadeObj,
      {
        opacity: 1,
        duration: 0.5,
        onUpdate: () => {
          root.traverse((obj) => {
            if (obj.isMesh && obj.material && 'opacity' in obj.material) {
              obj.material.opacity = fadeObj.opacity;
            }
          });
        },
      },
      0
    );

  timelines.push(fadeTL);

  // Quote mark weighted‑settle
  const settleTL = gsap.timeline({ delay: 0.5 });
  settleTL.to(
    quoteMark.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    },
    0
  );

  timelines.push(settleTL);

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    root.traverse((obj) => {
      if (obj.isMesh) {
        if (obj.geometry) obj.geometry.dispose();
        if (obj.material) obj.material.dispose();
      }
    });
  };

  root.userData.handlers = {};

  return root;
}
